class Solution {
  public long[] unmarkedSumArray(int[] nums, int[][] queries) {
    int n = nums.length;
    long sum = 0;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) {
      sum += nums[i];
      order[i] = i;
    }
    Arrays.sort(
        order,
        (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b));
    boolean[] marked = new boolean[n];
    long[] answer = new long[queries.length];
    int next = 0; // first position in `order` that may still be unmarked
    for (int q = 0; q < queries.length; q++) {
      int index = queries[q][0], k = queries[q][1];
      if (!marked[index]) {
        marked[index] = true;
        sum -= nums[index];
      }
      while (k > 0 && next < n) {
        int i = order[next++];
        if (marked[i]) continue; // already marked elements do not count towards k
        marked[i] = true;
        sum -= nums[i];
        k--;
      }
      answer[q] = sum;
    }
    return answer;
  }
}
